BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP-115-2-025','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第38條（私立學校、團體及民營事業機構員工總人數六十七人以上之定額進用），最後修正公布日：第38條 2011-02-01，本題考試日 2026-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP104-1-23','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考身心障礙者權益保障法第5條（身心障礙者定義）、第7條（需求評估）、第14條（身心障礙證明效期）及第19條（個別化、多元化服務）。第5條、第7條、第19條考試日後未再修正；第14條於 2021-01-20 修正，增訂無註記有效期間之身心障礙證明，但有效期間最長五年之規定未變，選項(B)仍錯誤，選項(C)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP104-2-30','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第60條、第100條（導盲犬自由出入公共場所，違反者限期改善及罰鍰、講習），最後修正公布日：第60條 2015-02-04、第100條 2015-02-04，本題考試日 2015-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP104-2-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第70條（身心障礙者經濟安全保障之方式），最後修正公布日：第70條 2007-07-11，本題考試日 2015-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP105-1-08','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第34條、第38條（支持性與庇護性就業服務、定額進用比例），最後修正公布日：第34條 2007-07-11、第38條 2011-02-01，本題考試日 2016-01-30 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP105-2-24','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第43條、第44條（身心障礙者就業基金之設置機關、用途及超額進用獎勵金），最後修正公布日：第43條 2007-07-11、第44條 2007-07-11，本題考試日 2016-07-23 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP106-1-25','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第63條、第64條（身心障礙福利機構財團法人登記及評鑑等第），最後修正公布日：第63條 2007-07-11、第64條 2014-06-04，本題考試日 2017-02-18 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP106-2-11','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。本題考身心障礙者權益保障法第13條（對鑑定及需求評估有異議者三十日內申請、以一次為限、負擔百分之四十費用）及第14條（重新鑑定及需求評估）。第13條考試日後未再修正；第14條於 2021-01-20 修正，增訂無註記有效期間之身心障礙證明，但障礙情況改變時應自行申請、主管機關得以書面通知於六十日內辦理，以及有效期間最長五年、效期屆滿前九十日內申請之規定均未變，選項(C)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP106-2-15','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第26條、第58條之1、第71條、第72條（醫療費用補助、復康巴士及經費補助不得有設籍限制、補助免納所得稅），最後修正公布日：第26條 2007-07-11、第58條之1 2011-06-29、第71條 2007-07-11、第72條 2007-07-11，本題考試日 2017-07-29 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP106-2-21','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。本題考身心障礙者權益保障法第53條（大眾運輸工具無障礙設施及設備、優先座位）及第56條（公共停車場身心障礙者專用停車位）。第56條考試日後未再修正；第53條於 2025-08-01 修正，將「博愛座」改稱「優先席」並改為供身心障礙者或有其他實際需要者優先乘坐，但比率不低於總座位數百分之十五及大眾運輸工具應規劃設置無障礙設施及設備之規定未變，選項(B)仍正確，選項(A)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP107-1-19','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題比較四部法律之通報時限。身心障礙者權益保障法第76條（應立即通報，至遲不得超過二十四小時）及老人福利法第43條（應通報，未定二十四小時之時限）考試日後均未再修正；兒童及少年福利與權益保障法第53條於 2019-04-24 修正、家庭暴力防治法第50條於 2023-12-06 修正，但應立即通報、至遲不得超過（逾）二十四小時之規定均未變，選項(C)仍為與法令規定不合者。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP107-2-17','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-07-28。本題比較四部法律之定期調查年限。老人福利法第10條（每五年老人生活狀況調查）、身心障礙者權益保障法第11條（至少每五年需求評估及服務調查研究）及社會救助法第13條（至少每五年低收入戶及中低收入戶生活狀況調查）考試日後均未再修正；兒童及少年福利與權益保障法第13條於 2019-04-24 修正，僅增訂六歲以下兒童死亡原因回溯分析，每四年進行兒童及少年現況調查之規定未變，選項(B)仍為非以五年為期限者。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP107-2-20','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第78條、第81條、第82條、第85條（緊急保護安置、協助聲請監護或輔助宣告、社區居住服務遭反對之協助、矯正機關之改善），最後修正公布日：第78條 2007-07-11、第81條 2011-02-01、第82條 2007-07-11、第85條 2007-07-11，本題考試日 2018-07-28 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP107-2-34','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第78條、第79條、第80條（緊急保護安置之要件、七十二小時及繼續安置三個月、安置費用由行為人支付），最後修正公布日：第78條 2007-07-11、第79條 2007-07-11、第80條 2009-07-08，本題考試日 2018-07-28 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP108-1-22','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-01-19。本題考身心障礙者權益保障法第53條（優先座位比率）、第56條（專用停車位百分之二）、第64條（機構評鑑分五個等第）及第69條之1（輔導視覺功能障礙者設立按摩勞動合作社）。第56條、第64條、第69條之1考試日後未再修正；第53條於 2025-08-01 修正，將「博愛座」改稱「優先席」，但比率不低於總座位數百分之十五之規定未變，選項(A)仍錯誤，選項(C)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP109-2-26','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第23條、第24條、第26條（醫院服務窗口及出院準備計畫列入醫院評鑑、特別門診、醫療費用補助），最後修正公布日：第23條 2011-02-01、第24條 2007-07-11、第26條 2007-07-11，本題考試日 2020-08-01 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP111-2-26','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第6條、第7條（鑑定報告十日內送達、鑑定費用由政府編列預算支應、需求評估因素），最後修正公布日：第6條 2015-12-16、第7條 2007-07-11，本題考試日 2022-07-30 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP112-1-26','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考身心障礙者權益保障法第70條（身心障礙者經濟安全保障之方式），最後修正公布日：第70條 2007-07-11，本題考試日 2023-02-18 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫